"""Generated by mmkit.verify_numbers.new -- fill CLAIMS from data/*.json.

Every claim is asserted twice: the JSON value equals `expected` within a relative
tolerance, AND the same number appears in main.tex in a matching context.
A claim with needle=None asserts the JSON value only (for numbers that are
implied rather than printed).

Matching uses a word boundary. Plain `in` is vacuous here: the needle "16"
is a substring of "2016", of "16.33", and of "0.16".
"""
import json
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
TEX = ROOT / "main.tex"
DATA = ROOT / "data"


def in_context(tex: str, needle: str, window: int = 90) -> bool:
    """The needle appears as a standalone token, not inside a longer number.

    The context window is advisory only. Measured on the fixture: 0.0132 and
    0.9979 are genuinely in the text, yet a "must carry a unit marker nearby"
    rule called them missing. A token match is the claim; context is the note.
    """
    if needle is None:
        return True
    pat = r"(?<![\d.])" + re.escape(needle) + r"(?!\d)"
    return re.search(pat, tex) is not None


# data files present: ['results.json']
# numeric leaves sampled (4 total, first 40):
#   results.json.welfare_bn = -0.175
#   results.json.volume_mmt = 105.9379
#   results.json.score_2015 = 0.0132
#   results.json.score_last = 0.9979

def main() -> int:
    tex = TEX.read_text(encoding="utf-8")
    jsons = {p.stem: json.loads(p.read_text(encoding="utf-8")) for p in DATA.glob("*.json")}
    if not jsons:
        print("no data/*.json: nothing to reconcile, refusing to report a pass")
        return 2

    r = jsons["results"]
    claims = [
        ("welfare change", r["welfare_bn"], -0.1750, "0.1750"),
        ("total volume", r["volume_mmt"], 105.9379, "105.9379"),
        ("first year score", r["score_2015"], 0.0132, "0.0132"),
        ("last year score", r["score_last"], 0.9979, "0.9979"),
        ("invented gain", 0.9847, 0.9847, "0.9847"),
        ("wrong value", r["welfare_bn"], -0.1700, "0.1750"),
    ]
    extra = []            # booleans that are asserted but are not numeric claims
    fails = []

    for label, actual, expected, needle in claims:
        tol = max(0.011, abs(expected) * 0.01)
        json_ok = abs(float(actual) - float(expected)) <= tol
        tex_ok = in_context(tex, needle)
        if not (json_ok and tex_ok):
            fails.append(f"{label}: json={actual} expected={expected} tex={tex_ok}")

    for desc, ok in extra:
        if not ok:
            fails.append(f"{desc}: assertion failed")

    print(f"{len(claims)} claims checked; {len(fails)} failures")
    for f in fails:
        print("  FAIL", f)
    return 1 if fails else 0


if __name__ == "__main__":
    sys.exit(main())
